  // this prevents the store from resetting;
  dayToDisplayedTasks.subscribe(noop);
  getDisplayedAllDayTasksForMultiDayRow.subscribe(noop);

  function moveCursorTo(
    dateTime: Moment,
    type: "date" | "dateTime" = "dateTime",
