import TinyGesture, { type Options } from "tinygesture";

export function createGestures(props: {
  ontap?: (event: MouseEvent | TouchEvent) => void;
  onlongpress?: (event: MouseEvent | TouchEvent) => void;
  onpanstart?: (event: MouseEvent | TouchEvent) => void;
  onpanend?: (event: MouseEvent | TouchEvent) => void;
  onpanmove?: (event: MouseEvent | TouchEvent) => void;
  options?: Partial<Options>;
}) {
  const { ontap, onlongpress, onpanstart, onpanend, onpanmove, options } =
    props;

  let pressed = false;

  return (el: HTMLElement) => {
    const gesture = new TinyGesture(el, options);

    gesture.on("tap", (event) => {
      if (pressed) {
        return;
      }

      ontap?.(event);
    });

    gesture.on("longpress", (event) => {
      pressed = true;

      onlongpress?.(event);
    });

    gesture.on("panend", (event) => {
      if (pressed) {
        setTimeout(() => {
          pressed = false;
        });
      }

      onpanend?.(event);
    });

    gesture.on("panstart", (event) => {
      onpanstart?.(event);
    });

    gesture.on("panmove", (event) => {
      onpanmove?.(event);
    });

    return {
      destroy() {
        gesture.destroy();
      },
    };
  };
}

import { on } from "svelte/events";
import { isNotVoid } from "typed-assert";

import { isEventOutside } from "../../util/dom";

export function pointerUpOutside(fn: (event: PointerEvent) => void) {
  return (el: HTMLElement) => {
    const off = on(document.body, "pointerup", (event) => {
      if (isEventOutside(event, el)) {
        fn(event);
      }
    });

    return {
      destroy() {
        off();
      },
    };
  };
}

/**
 * An action factory that lets you fire some callback when the event is outside of a registered set of elements.
 */
export function createPointerUpOutsideAction(
  fn: (event: PointerEvent) => void,
) {
  const registry: Set<HTMLElement> = new Set();

  let bodyTeardownFn: (() => void) | undefined;

  function init(el: HTMLElement) {
    registry.add(el);

    if (bodyTeardownFn) {
      return;
    }

    bodyTeardownFn = on(document.body, "pointerup", (event) => {
      if (Array.from(registry).every((el) => isEventOutside(event, el))) {
        fn(event);
      }
    });
  }

  function teardown(el: HTMLElement) {
    registry.delete(el);

    if (registry.size === 0) {
      isNotVoid(bodyTeardownFn);
      bodyTeardownFn();
      bodyTeardownFn = undefined;
    }
  }

  return (el: HTMLElement) => {
    init(el);

    return {
      destroy(el: HTMLElement) {
        teardown(el);
      },
    };
  };
}

import { identity } from "lodash/fp";

type Entries<T> = {
  [K in keyof T]: [K, T[K]];
}[keyof T][];

type IdentityGetters<T> = Partial<{
  [Prop in keyof T]: (value: T[Prop]) => string;
}>;

/**
 * Detect change in an object using custom identity functions for each object prop if needed
 *
 * @param initialProps
 * @param identityGetters
 */
export function createMemo<PropsType>(
  initialProps: PropsType,
  identityGetters: IdentityGetters<PropsType>,
) {
  let previousProps: PropsType = initialProps;

  function shouldUpdate(newProps: PropsType) {
    for (const [propKey, propValue] of Object.entries(
      // @ts-ignore
      newProps,
    ) as Entries<PropsType>) {
      const previousValue = previousProps[propKey];
      const identityFn = identityGetters?.[propKey] || identity;
      const propChanged = identityFn(propValue) !== identityFn(previousValue);

      if (propChanged) {
        previousProps = newProps;

        return true;
      }
    }

    return false;
  }

  return shouldUpdate;
}

import { derived, writable } from "svelte/store";

import { getObsidianContext } from "../../context/obsidian-context";
import type { TaskLocation } from "../../task-types";

export function hoverPreview(task: { location?: TaskLocation }) {
  return (el: HTMLElement) => {
    const { isModPressed, showPreview } = getObsidianContext();
    let currentEvent: MouseEvent | undefined;

    const hovering = writable(false);

    function handleMouseEnter(event: MouseEvent) {
      currentEvent = event;
      hovering.set(true);
    }

    function handleMouseLeave(event: MouseEvent) {
      currentEvent = undefined;
      hovering.set(false);
    }

    el.addEventListener("mouseenter", handleMouseEnter);
    el.addEventListener("mouseleave", handleMouseLeave);

    const shouldShowPreview = derived(
      [isModPressed, hovering],
      ([$isModPressed, $hovering]) => {
        return $isModPressed && $hovering;
      },
    );

    const unsubscribe = shouldShowPreview.subscribe((newValue) => {
      if (newValue && task.location?.path && currentEvent) {
        showPreview(
          el,
          currentEvent,
          task.location.path,
          task.location.position?.start?.line,
        );
      }
    });

    return {
      destroy() {
        el.removeEventListener("mouseenter", handleMouseEnter);
        el.removeEventListener("mouseleave", handleMouseLeave);
        unsubscribe();
      },
    };
  };
}

import { get, type Readable, type Writable } from "svelte/store";

import { vibrationDurationMillis } from "../../../constants";
import type { LocalTask } from "../../../task-types";
import type { OnUpdateFn } from "../../../types";

import type { EditOperation } from "./types";

interface UseEditActionsProps {
  baselineTasks: Writable<LocalTask[]>;
  editOperation: Writable<EditOperation | undefined>;
  tasksWithPendingUpdate: Readable<LocalTask[]>;
  onUpdate: OnUpdateFn;
}

export function useEditActions({
  editOperation,
  baselineTasks,
  tasksWithPendingUpdate,
  onUpdate,
}: UseEditActionsProps) {
  function startEdit(operation: EditOperation) {
    navigator.vibrate?.(vibrationDurationMillis);
    editOperation.set(operation);
  }

  function cancelEdit() {
    editOperation.set(undefined);
  }

  async function confirmEdit() {
    const currentOperation = get(editOperation);

    if (currentOperation === undefined) {
      return;
    }

    const oldBase = get(baselineTasks);
    const currentTasks = get(tasksWithPendingUpdate);

    baselineTasks.set(currentTasks);
    editOperation.set(undefined);

    const succeeded = await onUpdate(
      oldBase,
      currentTasks,
      currentOperation.mode,
    );

    if (!succeeded) {
      baselineTasks.set(oldBase);
    }
  }

  return {
    startEdit,
    confirmEdit,
    cancelEdit,
  };
}

import type { Overlap } from "../types";

export function getHorizontalPlacing(overlap?: Overlap) {
  const spanPercent = overlap ? (overlap.span / overlap.columns) * 100 : 100;
  const offsetPercent = overlap ? (100 / overlap.columns) * overlap.start : 0;

  return {
    spanPercent,
    offsetPercent,
  };
}

export type HorizontalPlacing = ReturnType<typeof getHorizontalPlacing>;

